def affichage():
    f = open("client.dat", "rb")
    eof = False
    while not eof:
        try:
            e = load(f)
            print(e.cin, e.code, e.np, e.rue, e.ville, e.tel)
            input("tapez entre ")
        except:
            eof = True
    f.close()

def recherche():
    f = open("client.dat", "rb")
    pos = -1
    i = 0
    eof = False
    cin = int(input("cin = "))
    while not eof:
        try:
            e = load(f)
            if e["cin"] == cin:
                pos = i
            i += 1
        except:
            eof = True
    f.close()
    return pos
